<map version="1.0.1"><node TEXT="AIGC课程菜单｜47门·75小时"><node TEXT="通用基础" COLOR="#225cc5"><node TEXT="F01 AIGC视频入门：一条片子的生产地图（1h）" COLOR="#225cc5"><node TEXT="面向第一次接触AI视频的学员，用一条商家短片追踪从需求到交付的全过程，建立任务、文件和人员之间的关系。" /><node TEXT="成果：一张个人视频生产流程图" /><node TEXT="前置：—" /><node TEXT="成片逆向拆解 · 10分钟"><node TEXT="区分文案、图像、视频、声音与包装" /><node TEXT="找到每种素材的来源" /></node><node TEXT="生产流程示范 · 15分钟"><node TEXT="串联任务书、脚本、分镜、资产、生成、剪辑和审核" /><node TEXT="明确每一步交接物" /></node><node TEXT="绘制生产地图 · 25分钟"><node TEXT="为一条15秒产品片安排步骤" /><node TEXT="标出可复用素材与人工判断点" /></node><node TEXT="地图讲评 · 10分钟"><node TEXT="检查漏项与先后关系" /><node TEXT="用失败案例说明返工如何向上游追溯" /></node></node><node TEXT="F02 把需求讲清楚：从客户想法到创作任务书（1h）" COLOR="#225cc5"><node TEXT="以“帮我做一条好看的宣传片”为起点，把模糊委托改写成可以报价、制作和验收的任务书。" /><node TEXT="成果：一页创作任务书与验收要点" /><node TEXT="前置：—" /><node TEXT="需求访谈 · 10分钟"><node TEXT="追问受众、渠道和观看后行动" /><node TEXT="区分客户愿望与必要信息" /></node><node TEXT="任务书示范 · 15分钟"><node TEXT="填写时长、比例、核心信息和品牌限制" /><node TEXT="列出客户应提供的素材" /></node><node TEXT="模拟客户沟通 · 25分钟"><node TEXT="将模糊需求改写成一页任务书" /><node TEXT="写明不确定事项与确认节点" /></node><node TEXT="验收校对 · 10分钟"><node TEXT="用任务书检查一条候选片" /><node TEXT="把“高级一点”改成可观察的修改要求" /></node></node><node TEXT="F03 选题与开头：让观众愿意继续看（1h）" COLOR="#225cc5"><node TEXT="围绕目标观众的真实问题设计选题，把“吸引人”落实为可验证的开头方案，避免把传播效果当作承诺。" /><node TEXT="成果：3个选题、3版开头与选择理由" /><node TEXT="前置：—" /><node TEXT="观众与场景 · 10分钟"><node TEXT="确定谁在何时观看" /><node TEXT="区分兴趣点、痛点与信息价值" /></node><node TEXT="开头拆解 · 15分钟"><node TEXT="比较结果前置、问题引入和反差开场" /><node TEXT="检查标题与内容是否一致" /></node><node TEXT="选题练习 · 25分钟"><node TEXT="为一个服务写三种选题与两个开头" /><node TEXT="标注画面、台词和兑现内容" /></node><node TEXT="方案评议 · 10分钟"><node TEXT="检查信息是否具体且可兑现" /><node TEXT="确定一项后续观察指标" /></node></node><node TEXT="F04 脚本小课：把一个卖点写成30秒故事（1h）" COLOR="#225cc5"><node TEXT="以一个产品或服务卖点为材料，在30秒内安排人物、问题、变化和行动，让文案能被拍成镜头。" /><node TEXT="成果：一份30秒脚本及压缩版" /><node TEXT="前置：—" /><node TEXT="卖点取舍 · 10分钟"><node TEXT="从功能表中选择一个利益点" /><node TEXT="明确观众相信它需要什么证据" /></node><node TEXT="结构示范 · 15分钟"><node TEXT="安排情境、阻碍、变化与行动" /><node TEXT="区分画面表达和旁白补充" /></node><node TEXT="脚本写作 · 25分钟"><node TEXT="完成分段画面与台词" /><node TEXT="朗读计时并删除重复信息" /></node><node TEXT="脚本讲评 · 10分钟"><node TEXT="核对卖点依据和前后因果" /><node TEXT="将无法拍摄的抽象句改写成动作" /></node></node><node TEXT="F05 分镜小课：把文字变成镜头清单（1h）" COLOR="#225cc5"><node TEXT="把一段脚本拆成镜头清单，学会用景别、视线、时长和切点组织信息，为画布和导演台提供明确输入。" /><node TEXT="成果：一份4—6镜分镜表" /><node TEXT="前置：—" /><node TEXT="镜头任务 · 10分钟"><node TEXT="区分交代环境、呈现动作和强调细节" /><node TEXT="判断何时需要切镜" /></node><node TEXT="分镜示范 · 15分钟"><node TEXT="填写景别、机位、人物动作、声音和时长" /><node TEXT="检查轴线与视线方向" /></node><node TEXT="分镜练习 · 25分钟"><node TEXT="把30秒脚本拆成4—6镜" /><node TEXT="绘制首尾构图并标出转场依据" /></node><node TEXT="连贯性检核 · 10分钟"><node TEXT="用分镜口述故事" /><node TEXT="发现信息重复和缺失并调整顺序" /></node></node><node TEXT="F06 提示词小课：从碰运气到可控修改（1h）" COLOR="#225cc5"><node TEXT="建立简洁、可迭代的提示词结构，学会区分必须保持的条件与允许变化的内容，形成可复用的修改记录。" /><node TEXT="成果：一组提示词与修改对照记录" /><node TEXT="前置：—" /><node TEXT="提示词诊断 · 10分钟"><node TEXT="识别空泛形容、冲突要求和过量动作" /><node TEXT="区分图像提示与视频提示" /></node><node TEXT="结构示范 · 15分钟"><node TEXT="组织主体、场景、动作、镜头与限制" /><node TEXT="说明参考图与文本的分工" /></node><node TEXT="对照练习 · 25分钟"><node TEXT="针对同一素材只改变一个变量" /><node TEXT="保存输入、结果和版本备注" /></node><node TEXT="结果归因 · 10分钟"><node TEXT="比较预期与实际差异" /><node TEXT="决定保留、重写或降低任务复杂度" /></node></node><node TEXT="F07 角色与产品一致性：建立可复用资产包（1h）" COLOR="#225cc5"><node TEXT="针对角色换脸、商品变形与服装漂移建立资产基准，学习用参照与检查表降低跨镜头返工。" /><node TEXT="成果：角色／产品卡及3张一致性候选图" /><node TEXT="前置：—" /><node TEXT="漂移识别 · 10分钟"><node TEXT="对照人物与商品失败样例" /><node TEXT="区分身份、服装、结构与色彩变化" /></node><node TEXT="资产包示范 · 15分钟"><node TEXT="建立角色正侧面与产品细节参照" /><node TEXT="统一命名、来源和固定描述" /><node TEXT="Redraw先批准资产描述，再生成并确认资产图；画布用文件浏览器与图层管理参考素材。" /></node><node TEXT="资产整理 · 25分钟"><node TEXT="为原创角色或商品建立基准页" /><node TEXT="写出不可变清单与允许变化项" /></node><node TEXT="一致性验收 · 10分钟"><node TEXT="比较三个候选镜头" /><node TEXT="标记需要返修的具体区域" /></node></node><node TEXT="F08 关键帧设计：先定画面，再生成运动（1h）" COLOR="#225cc5"><node TEXT="在生成视频之前先确定关键构图，用首帧与目标尾帧约束信息表达，减少先生成再猜测的成本。" /><node TEXT="成果：一组首尾画面与动作说明" /><node TEXT="前置：—" /><node TEXT="画面任务 · 10分钟"><node TEXT="分析首帧建立的信息与尾帧留下的问题" /><node TEXT="区分关键帧与普通参考图" /></node><node TEXT="构图示范 · 15分钟"><node TEXT="安排主体位置、留白、景深与动作空间" /><node TEXT="检查首尾的空间关系" /></node><node TEXT="关键帧练习 · 25分钟"><node TEXT="制作同一镜头的起始构图和目标结束构图" /><node TEXT="写出中间动作路径" /><node TEXT="Redraw生成本段尾帧后，确认下一段参考素材已引用；画布关键帧输入按所选模型支持方式设置。" /></node><node TEXT="可行性讲评 · 10分钟"><node TEXT="排查视角突变、遮挡和形态变化" /><node TEXT="过大变化拆成多个镜头" /></node></node><node TEXT="F09 视频生成诊断：镜头为什么失败（1h）" COLOR="#225cc5"><node TEXT="围绕一个失败镜头建立诊断顺序，在改素材、改提示、缩短镜头和重拍之间作选择。" /><node TEXT="成果：一个镜头的修复前后对照" /><node TEXT="前置：—" /><node TEXT="缺陷分类 · 10分钟"><node TEXT="区分身份漂移、动作断裂、镜头失控和物理失真" /><node TEXT="记录发生时点" /></node><node TEXT="排查示范 · 15分钟"><node TEXT="依次核对输入素材、动作数量、遮挡和时长" /><node TEXT="避免一次改动全部设置" /><node TEXT="区分任务中心中的生成失败与画面质量失败；按实际报错检查输入长度、媒体大小、渠道与额度。" /></node><node TEXT="修订实验 · 25分钟"><node TEXT="为一段失败片提出两条修复路径" /><node TEXT="实际测试一项并保留前后对照" /></node><node TEXT="成本复盘 · 10分钟"><node TEXT="比较质量、耗时与重试次数" /><node TEXT="说明继续生成或改用剪辑的理由" /></node></node><node TEXT="F10 配音与声音：让画面有节奏和情绪（1h）" COLOR="#225cc5"><node TEXT="为短片安排人声、音乐和环境声，让音轨承担信息与节奏；通过听辨和响度检查发现常见问题。" /><node TEXT="成果：一段20—30秒声音设计练习" /><node TEXT="前置：—" /><node TEXT="声音拆解 · 10分钟"><node TEXT="识别人声、环境、音效与音乐的作用" /><node TEXT="标出声音与画面的信息重复" /></node><node TEXT="配音示范 · 15分钟"><node TEXT="标注停连、重音与情绪" /><node TEXT="检查专有名词和数字读音" /></node><node TEXT="声音练习 · 25分钟"><node TEXT="为短片配置三层音轨" /><node TEXT="调整人声优先关系与入出点" /><node TEXT="画布工具节点可选视频配音或剧本角色配音；先检查必填输入，再逐句核对结果，音色克隆仅用于已授权声音。" /></node><node TEXT="听审讲评 · 10分钟"><node TEXT="用耳机和扬声器检查失真、遮蔽与突兀切断" /><node TEXT="核对音乐来源" /></node></node><node TEXT="F11 剪辑与包装：把镜头组装成片（1h）" COLOR="#225cc5"><node TEXT="把分散的生成镜头剪成有信息顺序的短片，重点练习节奏、字幕、声音和导出检查。" /><node TEXT="成果：一条15—30秒练习成片" /><node TEXT="前置：—" /><node TEXT="粗剪结构 · 10分钟"><node TEXT="按任务书排列镜头" /><node TEXT="删去重复信息与无效等待" /></node><node TEXT="包装示范 · 15分钟"><node TEXT="设置字幕层级、品牌落版和安全区域" /><node TEXT="保持声音连续" /></node><node TEXT="剪辑练习 · 25分钟"><node TEXT="完成一次粗剪到精剪" /><node TEXT="统一镜头比例并处理明显跳切" /></node><node TEXT="导出复查 · 10分钟"><node TEXT="核对清晰度、比例、字幕错字和黑帧" /><node TEXT="完整播放最终文件" /><node TEXT="分别检查成片文件与工程备份；遇播放兼容问题，检查编码并用目标播放环境测试，不能仅凭MP4扩展名判断。" /></node></node><node TEXT="F12 成片审核：质量、授权与AI标识（1h）" COLOR="#225cc5"><node TEXT="建立发布前的检查流程，区分画面质量、事实准确、素材权限和平台标识要求，形成可交接的审核记录。" /><node TEXT="成果：作品自查表与素材来源表" /><node TEXT="前置：—" /><node TEXT="审核分层 · 10分钟"><node TEXT="区分技术质量、内容事实、肖像声音与版权材料" /><node TEXT="确定审核负责人" /></node><node TEXT="案例核对 · 15分钟"><node TEXT="追踪图片、音乐、角色和商标的来源记录" /><node TEXT="查找拟发布平台的当前标识入口" /></node><node TEXT="审核练习 · 25分钟"><node TEXT="逐项检查课堂样片" /><node TEXT="将缺陷标为修订、待核实或可交付" /><node TEXT="分享工程前检查节点配置与本地路径，排除账号密钥和恢复码；备份文件不等于素材公开传播授权。" /></node><node TEXT="交接复核 · 10分钟"><node TEXT="整理授权记录、版本与生成说明" /><node TEXT="对待确认事项设置阻断点" /></node></node><node TEXT="F13 镜头调度：把视频提示词写成拍摄施工单（1h）" COLOR="#225cc5"><node TEXT="以一个五秒镜头为单位，把“画面好看但动作失控”转化为可执行的拍摄设计。课程串联人物表演、摄影机路径、环境反馈与最终构图，训练从导演意图到视频提示词的表达。" /><node TEXT="成果：镜头施工单＋5秒测试或候选片分析＋变量对照表" /><node TEXT="前置：无硬性前置，建议先学F05、F06、F08" /><node TEXT="镜头蓝图与任务 · 10分钟"><node TEXT="回答主体、初态、动作、机位路径、环境反应、尾帧六问" /><node TEXT="把情绪改写为眼神、手部和呼吸" /></node><node TEXT="表演与空间示范 · 15分钟"><node TEXT="拆解准备、发力、余势及触发—反应顺序" /><node TEXT="用景别、机位高度、路径终点和前中后景约束镜头" /></node><node TEXT="五秒镜头实验 · 25分钟"><node TEXT="填写镜头施工单并组织角色、光线、材质与物理反馈" /><node TEXT="固定素材逐次验证2—3个变量并记录实际结果" /></node><node TEXT="结果评议与拆镜 · 10分钟"><node TEXT="检查动作因果、角色身份和尾帧落点" /><node TEXT="多人表演或复杂转场失控时拆镜并在剪辑中完成" /></node></node></node><node TEXT="工具入门" COLOR="#7040b4"><node TEXT="T01 画布工具上手：做出第一条产品短片（2h）" COLOR="#7040b4"><node TEXT="以10—15秒产品短片为任务，从工作空间创建画布，配置并连接AI文本、AI图片和AI视频节点。重点检查下游实际读取的文本与参考素材，学会用图层定位、候选比较和工程备份组织创作。" /><node TEXT="成果：一条10—15秒、2—3镜产品练习片" /><node TEXT="前置：—" /><node TEXT="创建画布与任务 · 15分钟"><node TEXT="从工作空间创建画布项目并命名" /><node TEXT="确认画幅、素材、可用渠道和预算" /></node><node TEXT="节点与连线示范 · 20分钟"><node TEXT="双击空白处添加并编号文本、图片与视频节点" /><node TEXT="从源节点输出拖至目标输入，检查参考素材与文本上下文，未填入时手动选择" /></node><node TEXT="生成与版本比较 · 45分钟"><node TEXT="先运行上游再运行下游，完成2—3个候选镜头" /><node TEXT="通过图层定位结果，修改一个问题并保存生成记录" /></node><node TEXT="剪辑与工程备份 · 25分钟"><node TEXT="下载素材并用配套剪辑完成短片" /><node TEXT="分别识别JSON与7Z用途，导入工程副本核对素材是否齐全" /></node><node TEXT="展示与验收 · 15分钟"><node TEXT="展示完成一条10—15秒产品短片与工程记录" /><node TEXT="逐项评价：任务链可复现；至少一次有效修改；文件可播放" /></node></node><node TEXT="T02 转绘工具上手：拆解并重做一段视频（2h）" COLOR="#7040b4"><node TEXT="用自有或授权短片认识Vimox Redraw的完整制作链路：由原视频反推事实，整理并确认通用资产，再改编、编译分镜和生成候选。课堂以一个角色、一个场景及一段5—10秒候选为目标，重点理解各阶段的审核与交接。" /><node TEXT="成果：一段5—10秒改编候选＋事实核对单＋资产确认记录" /><node TEXT="前置：—" /><node TEXT="项目与原片导入 · 15分钟"><node TEXT="创建项目并保存恢复码，在设置中确认地区、对白语言、画幅与模型" /><node TEXT="选择本地文件或URL，检查截取范围和自动分集" /></node><node TEXT="原片与资产审核 · 20分钟"><node TEXT="点击分析原片并在任务中心查看进度，人工核对人物、场景与物品" /><node TEXT="整理通用资产，先审核并批准描述，再生成和确认资产图" /></node><node TEXT="改编与候选生成 · 45分钟"><node TEXT="审查并开始改编，在改编与连续性中核对内容后编译生成分镜" /><node TEXT="在生成工作台检查提示词与参考素材，生成一个片段候选" /></node><node TEXT="尾帧与成片检查 · 25分钟"><node TEXT="对已选候选生成本段尾帧，检查是否加入下一段参考素材" /><node TEXT="用预生成片段演示相邻衔接，再配套剪辑与导出" /></node><node TEXT="展示与验收 · 15分钟"><node TEXT="展示提交一段5—10秒改编候选、原片事实核对单与资产确认记录" /><node TEXT="逐项评价：原片事实核对清楚；描述与资产图均经确认；分镜及候选能够追溯" /></node></node><node TEXT="T03 导演台上手：从短剧本到剧情样片（2h）" COLOR="#7040b4"><node TEXT="以单场景短剧本为材料，认识导演台中剧本、角色、分镜与成片的关联，完成一次小规模端到端练习。" /><node TEXT="成果：一条20—30秒、单场景剧情练习片" /><node TEXT="前置：—" /><node TEXT="剧本准备 · 15分钟"><node TEXT="限定人物、地点和20—30秒剧情" /><node TEXT="确认素材与配套声音能力" /></node><node TEXT="流程示范 · 20分钟"><node TEXT="组织剧本、角色与场景资产" /><node TEXT="检查自动拆分结果并修订镜头任务" /></node><node TEXT="剧情生成 · 45分钟"><node TEXT="完成单场景关键镜头" /><node TEXT="保留人物描述和生成记录" /></node><node TEXT="成片整理 · 25分钟"><node TEXT="排列对白和镜头反应" /><node TEXT="检查人物关系、节奏与导出文件" /></node><node TEXT="展示、评价与迁移 · 15分钟"><node TEXT="展示完成20—30秒剧情样片与镜头清单" /><node TEXT="按以下标准自评与互评：剧本信息落地；角色可辨；故事能够理解" /></node></node></node><node TEXT="案例实战" COLOR="#086a56"><node TEXT="P01 TVC广告：做一条15秒品牌概念片（2h）" COLOR="#086a56"><node TEXT="围绕一个品牌利益点制作15秒概念广告，体验从创意提案到镜头选择和品牌落版的完整小项目。" /><node TEXT="成果：一条15秒TVC概念样片与创意说明" /><node TEXT="前置：T01" /><node TEXT="品牌简报 · 15分钟"><node TEXT="明确受众、承诺和证据" /><node TEXT="选择单一视觉概念" /></node><node TEXT="创意预演 · 20分钟"><node TEXT="写15秒结构与3—4镜分镜" /><node TEXT="建立产品和色彩基准" /></node><node TEXT="画布制作 · 45分钟"><node TEXT="生成主视觉及关键动态镜头" /><node TEXT="比较候选并修订产品或动作问题" /><node TEXT="用画布AI表格组织镜头，再用分镜生成器生成关键图；检查每行与输出对应，先验证单镜再批量。" /></node><node TEXT="广告精剪 · 25分钟"><node TEXT="安排节奏、声音和落版" /><node TEXT="检查品牌识别与文字准确" /></node><node TEXT="展示、评价与迁移 · 15分钟"><node TEXT="展示完成15秒品牌概念片和创意说明" /><node TEXT="按以下标准自评与互评：卖点可感知；产品识别稳定；落版清楚" /></node></node><node TEXT="P02 电商产品视频：让商品卖点可视化（2h）" COLOR="#086a56"><node TEXT="从真实商品资料提取一个使用价值，用场景与细节镜头呈现卖点，并保留可核对的商品信息。" /><node TEXT="成果：一条15—20秒产品展示样片" /><node TEXT="前置：T01" /><node TEXT="商品拆解 · 15分钟"><node TEXT="核实功能与外观资料" /><node TEXT="选择一个使用场景" /></node><node TEXT="镜头设计 · 20分钟"><node TEXT="安排痛点、产品出现和利益呈现" /><node TEXT="列出标识与结构不可变项" /></node><node TEXT="素材制作 · 45分钟"><node TEXT="生成环境和辅助镜头" /><node TEXT="保留真实商品层或选用可靠候选" /><node TEXT="参考教程的产品名称、卖点、产品图片输入结构；把这些输入连接到AI文本和AI视频，检查实际引用结果。" /></node><node TEXT="卖点包装 · 25分钟"><node TEXT="添加简洁说明和行动提示" /><node TEXT="检查文字、结构与功能表述" /></node><node TEXT="展示、评价与迁移 · 15分钟"><node TEXT="展示完成15—20秒电商产品视频和商品核对表" /><node TEXT="按以下标准自评与互评：信息真实；主体清楚；场景支持卖点" /></node></node><node TEXT="P03 本地商家宣传：一条片讲清到店理由（2h）" COLOR="#086a56"><node TEXT="围绕一家本地商户的真实服务制作到店宣传，把门店特色、顾客理由和行动信息压缩成一条短片。" /><node TEXT="成果：一条20—30秒商家宣传样片" /><node TEXT="前置：T01" /><node TEXT="门店任务 · 15分钟"><node TEXT="收集服务、地址和营业信息" /><node TEXT="确定一类目标顾客" /></node><node TEXT="内容设计 · 20分钟"><node TEXT="选择一个到店理由" /><node TEXT="安排环境、体验与行动信息" /></node><node TEXT="画面制作 · 45分钟"><node TEXT="结合自摄门店素材与AI辅助画面" /><node TEXT="保持场景和服务真实性" /><node TEXT="用文件浏览器绑定门店素材目录，将已确认素材拖到画布；以编号节点组织主镜头和行动信息。" /></node><node TEXT="成片验收 · 25分钟"><node TEXT="控制20—30秒节奏" /><node TEXT="复核价格有效期、地址与联系方式" /></node><node TEXT="展示、评价与迁移 · 15分钟"><node TEXT="展示完成20—30秒门店短片和发布信息表" /><node TEXT="按以下标准自评与互评：理由具体；信息可核验；行动入口清楚" /></node></node><node TEXT="P04 产品与服务讲解：把复杂流程讲明白（2h）" COLOR="#086a56"><node TEXT="选取一个产品或服务流程，采用图解、示范与旁白讲清步骤，让观众知道下一步应该做什么。" /><node TEXT="成果：一条30—45秒流程讲解样片" /><node TEXT="前置：T01" /><node TEXT="流程界定 · 15分钟"><node TEXT="选择一个使用任务" /><node TEXT="识别起点、关键条件和完成标志" /></node><node TEXT="讲解脚本 · 20分钟"><node TEXT="将流程拆成3—4步" /><node TEXT="为每步选择演示或图解" /></node><node TEXT="素材生产 · 45分钟"><node TEXT="制作步骤画面和旁白" /><node TEXT="避免生成错误按钮、界面或操作细节" /><node TEXT="用AI表格整理步骤与画面任务，再生成分镜图；界面和操作细节以真实截图或演示为准。" /></node><node TEXT="理解测试 · 25分钟"><node TEXT="剪成30—45秒" /><node TEXT="请同伴复述步骤并修订歧义" /></node><node TEXT="展示、评价与迁移 · 15分钟"><node TEXT="展示完成流程讲解短片与步骤检查表" /><node TEXT="按以下标准自评与互评：步骤正确；画面对应；观众能复述" /></node></node><node TEXT="P05 数字人口播：做一条可信的讲解视频（2h）" COLOR="#086a56"><node TEXT="从授权人物图和明确的讲稿出发，在画布中建立口播素材链。主要使用教程明确介绍的“真实数字人”工具，以人物图片和参考音频驱动短口播；同时认识AI视频节点中的数字人模型路线，按当前界面核对必填输入。" /><node TEXT="成果：一条30—45秒数字人口播样片" /><node TEXT="前置：T01" /><node TEXT="人物与讲稿 · 15分钟"><node TEXT="明确授权形象及发言身份" /><node TEXT="将30—45秒口语稿拆成适合所选工具的短段并标注停连" /></node><node TEXT="两条路线示范 · 20分钟"><node TEXT="工具节点选择真实数字人，填写人物图与参考音频，按需补动作提示词" /><node TEXT="在AI视频模型区搜索数字人，对照输入要求，选择一条作为主练路线" /></node><node TEXT="分段口播生成 · 45分钟"><node TEXT="生成或上传配音，连接人物图与音频并核对必填参数" /><node TEXT="逐段运行、检查口型与读音，保存通过的候选" /></node><node TEXT="剪辑与讲解核对 · 25分钟"><node TEXT="用配套剪辑连接短段和辅助画面" /><node TEXT="检查数字、专名、停顿与字幕，并记录失配时点" /></node><node TEXT="展示与验收 · 15分钟"><node TEXT="展示完成数字人讲解样片和逐句审核记录" /><node TEXT="逐项评价：内容准确；身份清楚；人声字幕一致" /></node></node><node TEXT="P06 教育微课：把一个知识点讲懂（2h）" COLOR="#086a56"><node TEXT="围绕一个可检验的知识点制作45—60秒微课，让例子、讲解和自测题共同服务学习目标。" /><node TEXT="成果：一条45—60秒教学样片及1道自测题" /><node TEXT="前置：T01" /><node TEXT="教学目标 · 15分钟"><node TEXT="写出学员学后能够完成的行为" /><node TEXT="限定一个知识点" /></node><node TEXT="微课设计 · 20分钟"><node TEXT="安排问题、解释、例子与自测" /><node TEXT="检查术语和知识来源" /></node><node TEXT="视听制作 · 45分钟"><node TEXT="生成示意画面并配旁白字幕" /><node TEXT="为关键概念保留观察时间" /><node TEXT="用画布AI文本组织讲稿，AI图片生成示意图，再连接AI视频或数字人工具；检查节点实际输入与知识准确性。" /></node><node TEXT="教学验收 · 25分钟"><node TEXT="请同伴作答自测并解释理由" /><node TEXT="据误解修改讲解或画面" /></node><node TEXT="展示、评价与迁移 · 15分钟"><node TEXT="展示完成微课、一道自测题及答案解析" /><node TEXT="按以下标准自评与互评：知识准确；目标题目一致；表达适合学员" /></node></node><node TEXT="P07 不出镜知识视频：用原创解释做内容（2h）" COLOR="#086a56"><node TEXT="从一个常见问题出发，以原创解释和可核对的信息做不出镜知识短片，建立资料到表达的转化方法。" /><node TEXT="成果：一条30—45秒知识视频样片" /><node TEXT="前置：T01" /><node TEXT="问题与资料 · 15分钟"><node TEXT="限定一个受众问题" /><node TEXT="记录关键结论的来源" /></node><node TEXT="解释结构 · 20分钟"><node TEXT="写30—45秒脚本" /><node TEXT="区分事实、类比与个人判断" /></node><node TEXT="画面组织 · 45分钟"><node TEXT="生成示意素材与信息图" /><node TEXT="用旁白承担必要逻辑" /><node TEXT="将资料摘要与核实后的讲稿分别保留为文本节点；只把通过审核的讲稿和图像传给生成节点。" /></node><node TEXT="知识审核 · 25分钟"><node TEXT="逐句核对事实和画面暗示" /><node TEXT="删除未经证实的结论" /></node><node TEXT="展示、评价与迁移 · 15分钟"><node TEXT="展示完成知识短片与信息来源表" /><node TEXT="按以下标准自评与互评：观点有依据；解释原创；示意不误导" /></node></node><node TEXT="P08 高传播创意短视频：反差、悬念与循环（2h）" COLOR="#086a56"><node TEXT="在同一创意上设计反差、悬念或循环结构，制作可以比较的开头版本，学习用实验思路改进表达。" /><node TEXT="成果：一条10—20秒创意样片＋两版开头方案" /><node TEXT="前置：T01" /><node TEXT="创意机制 · 15分钟"><node TEXT="拆解反差、信息缺口和循环结尾" /><node TEXT="辨认过度承诺" /></node><node TEXT="版本设计 · 20分钟"><node TEXT="为10—20秒主体写两种开头" /><node TEXT="保持其余变量一致" /></node><node TEXT="镜头制作 · 45分钟"><node TEXT="生成关键反差或揭示画面" /><node TEXT="完成主体与两个开头的拼接" /><node TEXT="复制已验证节点链并只更改开头变量；通过节点命名与图层定位区分两个版本，避免混用候选。" /></node><node TEXT="测试计划 · 25分钟"><node TEXT="核对开头是否兑现" /><node TEXT="确定观察时段和指标，避免凭单条数据归因" /></node><node TEXT="展示、评价与迁移 · 15分钟"><node TEXT="展示完成创意短片与两版开头" /><node TEXT="按以下标准自评与互评：结构完整；对照变量清楚；不承诺传播结果" /></node></node><node TEXT="P09 风格转绘：让同一段素材呈现新表达（2h）" COLOR="#086a56"><node TEXT="以Redraw原片分析结果为起点，先确认故事信息，再用人物、服装和场景资产定义视觉语气。课程比较同一叙事任务的两种风格候选，学习用资产和分镜控制改编方向。" /><node TEXT="成果：一段转绘样片＋原片对照与风格说明" /><node TEXT="前置：T02" /><node TEXT="原片事实与任务 · 15分钟"><node TEXT="核对人物、事件和场景分析" /><node TEXT="选择一段能够独立理解的叙事单元" /></node><node TEXT="双风格资产设计 · 20分钟"><node TEXT="用媒介、色彩、光线与材质写两组资产描述" /><node TEXT="先检查描述再批准，生成并确认代表性资产图" /></node><node TEXT="改编与候选比较 · 45分钟"><node TEXT="将确认的资产用于改编与分镜编译" /><node TEXT="固定故事任务生成两个短候选，比较身份与场景稳定性" /></node><node TEXT="修订与选择 · 25分钟"><node TEXT="对照资产、分镜和候选定位偏差" /><node TEXT="选择一版剪辑，并说明风格如何服务原片信息" /></node><node TEXT="展示与验收 · 15分钟"><node TEXT="展示完成风格转绘样片与双版本对照" /><node TEXT="逐项评价：风格有依据；动作可读；变化服务表达" /></node></node><node TEXT="P10 视频出海本地化：从换语言到换表达（2h）" COLOR="#086a56"><node TEXT="从项目设置开始选择目标国家或地区与对白语言，将文化适配前置到原片事实和资产改编。用一段15—30秒样片练习画面、文本与表达的同步本地化，导出后人工核对语言和文化信息。" /><node TEXT="成果：一条15—30秒本地化样片＋双语脚本与改写表" /><node TEXT="前置：T02" /><node TEXT="目标地区与项目设置 · 15分钟"><node TEXT="在项目与本土化中选择地区和对白语言" /><node TEXT="确认画幅、分辨率与帧率并保存" /></node><node TEXT="事实与语境审查 · 20分钟"><node TEXT="核对源片中的称谓、单位、道具和文化符号" /><node TEXT="写出保持含义与允许改写的清单" /></node><node TEXT="本地化改编 · 45分钟"><node TEXT="批准适配后的资产描述与资产图，再核对改编内容并编译分镜" /><node TEXT="生成一段候选，建立原文、目标语与画面对应表" /></node><node TEXT="语言与交付复核 · 25分钟"><node TEXT="人工检查台词、专名、语气及字幕" /><node TEXT="必要时配套配音，导出后完整播放" /></node><node TEXT="展示与验收 · 15分钟"><node TEXT="展示完成本地化短片与双语文本表" /><node TEXT="逐项评价：语义准确；表达适配；版本资料齐全" /></node></node><node TEXT="P11 AI短剧：完成一个有反转的剧情场景（2h）" COLOR="#086a56"><node TEXT="在一个地点、有限人物内设计反转，使用导演台完成冲突建立、角色反应与信息揭示。" /><node TEXT="成果：一条30—45秒短剧场景样片" /><node TEXT="前置：T03" /><node TEXT="剧情任务 · 15分钟"><node TEXT="明确人物目标、阻碍与反转" /><node TEXT="将故事限定在30—45秒" /></node><node TEXT="剧本分镜 · 20分钟"><node TEXT="安排对白和反应镜头" /><node TEXT="建立角色、道具和空间基准" /></node><node TEXT="导演台制作 · 45分钟"><node TEXT="生成关键镜头与补充反应" /><node TEXT="检查视线、身份和情绪承接" /></node><node TEXT="剧情精剪 · 25分钟"><node TEXT="校对白时序与揭示点" /><node TEXT="删去解释重复并处理跳切" /></node><node TEXT="展示、评价与迁移 · 15分钟"><node TEXT="展示完成反转剧情样片和剧本分镜表" /><node TEXT="按以下标准自评与互评：冲突可懂；反转有铺垫；角色关系稳定" /></node></node><node TEXT="P12 AI漫剧：把原创故事做成动态片段（2h）" COLOR="#086a56"><node TEXT="将原创故事改成动态漫片段，通过有限运动、分层画面与对白节奏建立叙事，而非追求所有画面同时运动。" /><node TEXT="成果：一条20—30秒漫剧样片＋后续两集梗概" /><node TEXT="前置：T03" /><node TEXT="故事选择 · 15分钟"><node TEXT="提取一个20—30秒场景" /><node TEXT="列出角色目标与情节转折" /></node><node TEXT="视觉设定 · 20分钟"><node TEXT="统一角色、画风和分层构图" /><node TEXT="选择需要运动的区域" /></node><node TEXT="片段制作 · 45分钟"><node TEXT="组织画面、镜头推进、对白与音效" /><node TEXT="避免无意义晃动" /></node><node TEXT="系列设计 · 25分钟"><node TEXT="完成片段剪辑" /><node TEXT="写后续两集梗概并检查角色设定延续" /></node><node TEXT="展示、评价与迁移 · 15分钟"><node TEXT="展示完成动态漫片段与两集故事提纲" /><node TEXT="按以下标准自评与互评：叙事清楚；运动有目的；设定可延续" /></node></node><node TEXT="P13 文旅与文化短片：让地方故事被看见（2h）" COLOR="#086a56"><node TEXT="选择一个地方故事或文化主题，用真实资料与艺术化画面构成20—30秒叙事，明确事实与想象的边界。" /><node TEXT="成果：一条20—30秒文旅文化样片" /><node TEXT="前置：T01/T03" /><node TEXT="主题核验 · 15分钟"><node TEXT="选择一个景点、人物或文化物件" /><node TEXT="记录可验证事实" /></node><node TEXT="叙事设计 · 20分钟"><node TEXT="从一个细节进入地方故事" /><node TEXT="标注真实记录与艺术想象" /></node><node TEXT="路径制作 · 45分钟"><node TEXT="用画布组织镜头或用导演台组织剧情" /><node TEXT="保持地标与文化标识准确" /><node TEXT="选择画布路线时用文件浏览器整理地方素材并按镜号命名；历史与文化事实先审核再进入生成节点。" /></node><node TEXT="文化复审 · 25分钟"><node TEXT="核对旁白、画面和来源" /><node TEXT="为艺术化重建安排必要说明" /></node><node TEXT="展示、评价与迁移 · 15分钟"><node TEXT="展示完成文旅文化短片与事实清单" /><node TEXT="按以下标准自评与互评：地方特征清楚；事实可信；表达有叙事" /></node></node><node TEXT="P14 实拍＋AI特效：做一个可用的创意镜头（2h）" COLOR="#086a56"><node TEXT="把一个自摄镜头与AI生成元素结合，练习光线、遮挡和接触关系，让特效成为可理解的创意。" /><node TEXT="成果：一段5—8秒特效镜头＋前后对照" /><node TEXT="前置：T01" /><node TEXT="创意与拍摄 · 15分钟"><node TEXT="限定5—8秒单镜头" /><node TEXT="规划机位、动作和留白" /></node><node TEXT="匹配示范 · 20分钟"><node TEXT="观察透视、光向、阴影与遮挡" /><node TEXT="选择需保留的实拍区域" /></node><node TEXT="素材合成 · 45分钟"><node TEXT="生成辅助元素并借助配套后期组合" /><node TEXT="修订边缘与接触位置" /><node TEXT="AI图片与AI视频节点制作辅助元素，精细遮挡和产品层交由配套合成；先验证单镜的光线与接触关系。" /></node><node TEXT="镜头验收 · 25分钟"><node TEXT="慢放检查漂浮、穿插与亮度差异" /><node TEXT="必要时降低运动复杂度" /></node><node TEXT="展示、评价与迁移 · 15分钟"><node TEXT="展示完成实拍与AI特效镜头及分层说明" /><node TEXT="按以下标准自评与互评：空间合理；光线匹配；特效意图清楚" /></node></node><node TEXT="P15 音乐视觉短片：把节奏变成画面（2h）" COLOR="#086a56"><node TEXT="把一段授权音乐的节奏和情绪转换成镜头变化，用重复、对比和切点构成音乐视觉练习。" /><node TEXT="成果：一条10—15秒音乐视觉片段" /><node TEXT="前置：T01" /><node TEXT="音乐拆解 · 15分钟"><node TEXT="选择10—15秒片段" /><node TEXT="标记重拍、停顿与情绪变化" /></node><node TEXT="视觉设计 · 20分钟"><node TEXT="选择一个形状或色彩动机" /><node TEXT="安排重复与变化的镜头" /></node><node TEXT="画面制作 · 45分钟"><node TEXT="生成关键视觉素材" /><node TEXT="保留足够剪辑余量并统一风格" /><node TEXT="在画布用编号文本记录节拍点，连接对应图像与视频节点；候选下载后在配套剪辑中校准切点。" /></node><node TEXT="节奏剪辑 · 25分钟"><node TEXT="依据节拍安排切点和运动变化" /><node TEXT="检查转场是否遮蔽音乐重点" /></node><node TEXT="展示、评价与迁移 · 15分钟"><node TEXT="展示完成音乐视觉片段与节拍分镜表" /><node TEXT="按以下标准自评与互评：音画呼应；视觉统一；素材来源清楚" /></node></node><node TEXT="P16 口播转绘：把真人讲解变成风格化主持（2h）" COLOR="#086a56"><node TEXT="将原口播拆成讲解信息与表演参考，在Redraw中校对事实、确认主持形象资产并重建短片。重点检查信息是否准确、人物是否稳定、对白是否可懂；精确音频驱动需求可衔接画布数字人流程。" /><node TEXT="成果：一条10—15秒主持改编片段＋信息与音画检查表" /><node TEXT="前置：T02" /><node TEXT="讲解原片分析 · 15分钟"><node TEXT="选取单人10—15秒口播，核对原片事实与信息顺序" /><node TEXT="区分必须表达的内容和仅供参考的原动作" /></node><node TEXT="主持资产确认 · 20分钟"><node TEXT="在通用资产中检查外观与服装描述并批准" /><node TEXT="生成形象图，确认后提交改编" /></node><node TEXT="主持片段重建 · 45分钟"><node TEXT="核对改编台词和分镜，检查参考素材后生成候选" /><node TEXT="记录嘴部、表情、台词及身份偏差" /></node><node TEXT="音画路线选择 · 25分钟"><node TEXT="按信息完整与听辨结果验收" /><node TEXT="精确音频驱动改走画布数字人，或采用旁白加辅助画面完成表达" /></node><node TEXT="展示与验收 · 15分钟"><node TEXT="展示提交10—15秒主持改编片段、信息对照及音画检查表" /><node TEXT="逐项评价：讲解信息准确；主持形象稳定；对白与画面经实际检查" /></node></node><node TEXT="P17 短剧转绘：把一场实拍戏改成新风格（2h）" COLOR="#086a56"><node TEXT="用自有或授权双人短场景，在Redraw内完成原片事实核对、角色资产确认、改编审查及分镜编译。按段生成候选并以尾帧参考辅助衔接，重建同一冲突及人物关系。" /><node TEXT="成果：一条15—25秒剧情转绘样片＋镜头对应表" /><node TEXT="前置：T02" /><node TEXT="原片与剧情事实 · 15分钟"><node TEXT="检查导入范围和分集边界，运行分析原片" /><node TEXT="核对两人关系、冲突、关键道具与事件先后" /></node><node TEXT="资产与改编审查 · 20分钟"><node TEXT="分别审核角色和场景描述，批准后生成并确认资产图" /><node TEXT="进入改编与连续性，检查改编是否改变关键事实" /></node><node TEXT="逐镜制作与尾帧 · 45分钟"><node TEXT="编译生成分镜，在生成工作台检查各段提示词和参照" /><node TEXT="逐段生成候选，生成尾帧并核对下一段引用" /></node><node TEXT="剧情合成与验收 · 25分钟"><node TEXT="按改编逻辑剪辑对白和反应" /><node TEXT="检查角色、视线、服饰、道具及声音衔接" /></node><node TEXT="展示与验收 · 15分钟"><node TEXT="展示完成剧情转绘片段和原片—成片镜头表" /><node TEXT="逐项评价：人物不混淆；冲突保留；切镜连贯" /></node></node><node TEXT="P18 真人转动漫：把表演迁移给原创角色（2h）" COLOR="#086a56"><node TEXT="用教程中“动作迁移”工具，将自摄动作参考视频与原创人物图片作为输入，制作5—10秒动漫表演。该路线在画布完成，适合强调原动作对应关系的任务，并与Redraw的剧情重建路线比较。" /><node TEXT="成果：一段5—10秒动漫表演片段＋动作对照" /><node TEXT="前置：T01，或具备画布节点操作能力" /><node TEXT="表演与素材准备 · 15分钟"><node TEXT="录制5—10秒单人低遮挡动作" /><node TEXT="选定原创角色图并核对身体可见区域" /></node><node TEXT="动作迁移节点示范 · 20分钟"><node TEXT="在画布工具中选择动作迁移" /><node TEXT="上传人物图和动作参考视频，核对所有必填项与下游输入" /></node><node TEXT="表演迁移试做 · 45分钟"><node TEXT="运行并对照人物姿态、重心和手势" /><node TEXT="只修改角色构图或源动作中的一项并保存对照" /></node><node TEXT="动作验收 · 25分钟"><node TEXT="逐段标注身份、肢体和视线偏差" /><node TEXT="区分风格变化、动作迁移与Redraw叙事重建的适用任务" /></node><node TEXT="展示与验收 · 15分钟"><node TEXT="展示完成动漫表演片段及动作对应记录" /><node TEXT="逐项评价：角色原创；动作可对应；能力边界说明清楚" /></node></node><node TEXT="P19 商品广告转绘：换场景，保留商品识别（2h）" COLOR="#086a56"><node TEXT="从原广告事实与镜头任务出发，用Redraw整理商品、场景与人物资产，改编广告环境并生成候选。对包装文字、形状和关键细节采用真实产品素材核对，必要时在配套剪辑合成中保留商品层。" /><node TEXT="成果：一条8—15秒广告变体＋商品一致性清单" /><node TEXT="前置：T02" /><node TEXT="广告与商品事实 · 15分钟"><node TEXT="核对原广告的卖点和商品资料" /><node TEXT="列出轮廓、颜色、标签等不可变项" /></node><node TEXT="资产改编 · 20分钟"><node TEXT="审核商品与场景描述，先确认代表图" /><node TEXT="规划环境变化及应由真实素材保留的区域" /></node><node TEXT="候选生成与产品对照 · 45分钟"><node TEXT="编译广告分镜并生成8—15秒候选" /><node TEXT="对照产品参照检查每个重要镜头，分离需要后期处理的问题" /></node><node TEXT="商品合成与验收 · 25分钟"><node TEXT="必要时在配套后期中使用真实产品层" /><node TEXT="检查文字、外形和功能表述，再完成声音与落版" /></node><node TEXT="展示与验收 · 15分钟"><node TEXT="展示完成广告变体与商品不可变清单" /><node TEXT="逐项评价：商品识别准确；环境服务卖点；无虚构功能" /></node></node><node TEXT="P20 文旅非遗转绘：让真实记录有视觉叙事（2h）" COLOR="#086a56"><node TEXT="将文化记录中的事实、对象和动作关系转为可核对的改编依据，借助Redraw资产审核与分镜重建形成10—20秒文化表达。关键技艺过程继续采用真实影像，艺术化生成主要承担环境与讲解。" /><node TEXT="成果：一条10—20秒文化转绘短片＋事实核对表" /><node TEXT="前置：T02" /><node TEXT="文化事实核对 · 15分钟"><node TEXT="导入并分析自有文化素材" /><node TEXT="检查地区、名称、人物、工具与操作顺序" /></node><node TEXT="资产与改编范围 · 20分钟"><node TEXT="审核文化标识和服饰描述，确认生成资产图" /><node TEXT="划分真实过程与可艺术化的环境内容" /></node><node TEXT="分段重建 · 45分钟"><node TEXT="核对改编及分镜，再生成风格化讲解片段" /><node TEXT="保留真实技艺镜头，与生成环境组合" /></node><node TEXT="文化复审 · 25分钟"><node TEXT="逐项核对画面与资料" /><node TEXT="标记艺术化重建，完善解说和来源记录" /></node><node TEXT="展示与验收 · 15分钟"><node TEXT="展示完成文化转绘短片与事实核对记录" /><node TEXT="逐项评价：文化信息准确；变化范围清楚；关键动作保留" /></node></node><node TEXT="P21 教学演示转绘：保留实拍步骤，重建讲解画面（2h）" COLOR="#086a56"><node TEXT="围绕一个操作学习目标，将准确的实拍步骤与生成的辅助讲解分开设计。Redraw用于分析原片、整理相关资产并重建情境或解释画面，关键手部接触与步骤继续用实拍呈现。" /><node TEXT="成果：一段10—20秒教学演示＋1道自测题" /><node TEXT="前置：T02" /><node TEXT="目标与实拍步骤 · 15分钟"><node TEXT="选低风险单一任务并核对操作顺序" /><node TEXT="标出必须保留实拍的手部、工具接触和完成标志" /></node><node TEXT="辅助讲解设计 · 20分钟"><node TEXT="核对原片事实与物品资产" /><node TEXT="批准只用于情境说明的资产与改编内容" /></node><node TEXT="讲解片段制作 · 45分钟"><node TEXT="编译并生成辅助镜头" /><node TEXT="用配套剪辑与关键实拍步骤组合，加入清楚的步骤提示" /></node><node TEXT="学习效果检核 · 25分钟"><node TEXT="让同伴按画面复述操作" /><node TEXT="用自测题检查关键步骤，发现误导时回用原片或修订讲解" /></node><node TEXT="展示与验收 · 15分钟"><node TEXT="展示完成教学演示片段与自测题解析" /><node TEXT="逐项评价：步骤正确；关键部位可见；题目检验目标" /></node></node><node TEXT="P22 多镜头转绘：解决角色与场景不连贯（2h）" COLOR="#086a56"><node TEXT="针对Redraw生成工作台的分段流程，练习共同资产确认、改编与连续性审查，以及“生成候选→生成本段尾帧→检查下一段参考”的交接。重点检查三个片段的角色、服饰、道具与构图延续。" /><node TEXT="成果：三镜连贯转绘片段＋连续性检查表" /><node TEXT="前置：T02" /><node TEXT="三段连续性任务 · 15分钟"><node TEXT="标出每段的起止状态、角色和道具位置" /><node TEXT="区分剧情连续性与画面连续性" /></node><node TEXT="共享资产与改编 · 20分钟"><node TEXT="确认统一角色、服装和场景资产" /><node TEXT="在改编与连续性中核对三段关系并编译分镜" /></node><node TEXT="候选与尾帧交接 · 45分钟"><node TEXT="生成首段候选并检查后生成本段尾帧" /><node TEXT="确认尾帧进入下一段参考素材，再依次生成后续片段" /></node><node TEXT="接缝验收 · 25分钟"><node TEXT="并排比较前段尾部与后段开头" /><node TEXT="修订参考、重生成或调整剪辑切点，记录采用理由" /></node><node TEXT="展示与验收 · 15分钟"><node TEXT="展示完成三镜连续片段和连续性检查表" /><node TEXT="逐项评价：角色统一；空间关系合理；差异处理可追踪" /></node></node><node TEXT="P23 转绘修复：处理闪烁、变形与口型偏差（2h）" COLOR="#086a56"><node TEXT="用Redraw失败案例练习两条排查线：任务失败先看任务中心与模型返回信息；生成成功但效果不合格则核对事实、资产、分镜及参考。比较精简提示词、重生成和剪辑替换的成本。" /><node TEXT="成果：一段5—10秒修复对照＋返修记录" /><node TEXT="前置：T02" /><node TEXT="故障分类 · 15分钟"><node TEXT="查看任务中心状态和具体报错" /><node TEXT="区分认证额度、输入限制、任务未完成与画面质量问题" /></node><node TEXT="输入排查 · 20分钟"><node TEXT="按当前错误提示检查长度，删除重复描述而保留人物、场景、动作与镜头任务" /><node TEXT="检查已批准资产和参考尾帧是否符合本段要求" /></node><node TEXT="修复实验 · 45分钟"><node TEXT="选择一个主要问题，对5—10秒片段实施精简重试或素材修订" /><node TEXT="记录原输入、修改、耗时与候选差异" /></node><node TEXT="返修决策 · 25分钟"><node TEXT="对比重生成与剪辑替换方案" /><node TEXT="口型、闪烁无法改善时改用配套后期、原片或简化镜头" /></node><node TEXT="展示与验收 · 15分钟"><node TEXT="展示完成修复前后对照与返修成本记录" /><node TEXT="逐项评价：缺陷定位准确；结果有改善证据；取舍合理" /></node></node><node TEXT="P24 短剧转绘出海：做好一个多语对白场景（2h）" COLOR="#086a56"><node TEXT="在Redraw项目与本土化设置中确定目标地区和对白语言，围绕双人关系审查原片事实、资产与改编对白。完成分镜编译和分段生成后，人工复核目标语的称谓、语气与剧情理解。" /><node TEXT="成果：一条15—25秒多语剧情样片＋双语台词表" /><node TEXT="前置：T02" /><node TEXT="地区语言与角色关系 · 15分钟"><node TEXT="在项目与本土化中保存目标地区和对白语言" /><node TEXT="核对原片人物关系、称谓和情绪节点" /></node><node TEXT="对白与资产适配 · 20分钟"><node TEXT="制作逐句双语台词表" /><node TEXT="检查角色资产、文化道具与改编内容是否改变原意" /></node><node TEXT="分镜与多语候选 · 45分钟"><node TEXT="编译分镜，核对每段提示词和参考素材" /><node TEXT="逐段生成并检查尾帧引用，记录实际对白与画面偏差" /></node><node TEXT="多语验收 · 25分钟"><node TEXT="人工复核称谓、专名、情绪和字幕" /><node TEXT="按需配套角色配音并调整切点，完整播放15—25秒样片" /></node><node TEXT="展示与验收 · 15分钟"><node TEXT="展示完成多语剧情样片与角色双语台词表" /><node TEXT="逐项评价：关系不变；情绪连贯；译文和字幕准确" /></node></node><node TEXT="P25 舞蹈与音乐转绘：保留动作，设计节奏（2h）" COLOR="#086a56"><node TEXT="用人物图片与动作参考视频在画布“动作迁移”工具中完成5—10秒表演片段。课堂专注肢体、重心与节拍，比较动作迁移结果和原动作的差异，形成明确的验收记录。" /><node TEXT="成果：一条5—10秒风格化表演＋动作检查表" /><node TEXT="前置：T01，或具备画布节点操作能力" /><node TEXT="动作与音乐选择 · 15分钟"><node TEXT="截取5—10秒低遮挡单人动作" /><node TEXT="标注重心变化、关节交叉与音乐重拍" /></node><node TEXT="动作迁移配置 · 20分钟"><node TEXT="在画布选择动作迁移工具" /><node TEXT="上传人物图与参考视频，确认构图、输入与生成规格" /></node><node TEXT="候选与动作对照 · 45分钟"><node TEXT="运行工具并检查脚底接触、手脚结构和动作轨迹" /><node TEXT="修订一项输入，保留前后对照" /></node><node TEXT="节拍包装 · 25分钟"><node TEXT="在配套剪辑中按音乐重拍安排切点" /><node TEXT="检查动作连续与授权素材记录" /></node><node TEXT="展示与验收 · 15分钟"><node TEXT="展示完成风格化表演与动作检查表" /><node TEXT="逐项评价：动作可辨；肢体稳定；节拍配合自然" /></node></node></node><node TEXT="职业交付" COLOR="#935418"><node TEXT="B01 接单与报价：把创作拆成可计价工作（1h）" COLOR="#935418"><node TEXT="把视频任务拆成可计价的工作项，学会说明修改次数、生成成本和交付边界，完成一次模拟报价。" /><node TEXT="成果：一份模拟报价单与服务范围说明" /><node TEXT="前置：—" /><node TEXT="任务拆分 · 10分钟"><node TEXT="识别策划、资产、生成、剪辑与审核工作" /><node TEXT="区分固定成本和不确定项" /></node><node TEXT="成本示范 · 15分钟"><node TEXT="计算工时、工具额度与外部素材支出" /><node TEXT="设置修改轮次和交付规格" /><node TEXT="按实际账号的渠道、模型和任务消耗记录成本；教程价格、免费额度和效率数字不作为固定报价承诺。" /></node><node TEXT="模拟报价 · 25分钟"><node TEXT="为课堂样片填写报价单" /><node TEXT="列出客户材料、周期和超范围处理" /></node><node TEXT="报价评议 · 10分钟"><node TEXT="解释每项费用的依据" /><node TEXT="检查遗漏的返工与沟通时间" /></node></node><node TEXT="B02 修改与交付：让客户意见变成任务（1h）" COLOR="#935418"><node TEXT="把客户的主观反馈转成带时点、优先级与验收标准的修改任务，建立有版本记录的交付包。" /><node TEXT="成果：一份交付包目录＋修改确认单" /><node TEXT="前置：—" /><node TEXT="反馈拆解 · 10分钟"><node TEXT="区分事实错误、审美偏好和范围变化" /><node TEXT="追问模糊意见" /></node><node TEXT="任务示范 · 15分钟"><node TEXT="标记时间码、问题、动作和确认人" /><node TEXT="约定反馈收口方式" /></node><node TEXT="返修练习 · 25分钟"><node TEXT="处理一组模拟意见" /><node TEXT="输出修改清单与版本说明" /></node><node TEXT="交付检核 · 10分钟"><node TEXT="整理成片、源文件约定、素材记录与说明" /><node TEXT="用清单模拟验收" /><node TEXT="画布JSON只交接结构配置，7Z用于含素材的工程迁移；导入副本检查缺失素材。Redraw恢复码与项目恢复文件分开交接，不写入公开作品页。" /></node></node><node TEXT="B03 作品集与获客：让客户看懂你能做什么（1h）" COLOR="#935418"><node TEXT="把课堂作品整理成客户能够理解的服务案例，通过目标、过程、结果与个人贡献说明自己的能力。" /><node TEXT="成果：一页作品集结构＋一项服务介绍" /><node TEXT="前置：—" /><node TEXT="客户定位 · 10分钟"><node TEXT="选择一类客户和一种视频服务" /><node TEXT="分析客户需要看到的证据" /></node><node TEXT="案例拆解 · 15分钟"><node TEXT="用任务、做法和结果说明样片" /><node TEXT="区分本人贡献与模板资源" /></node><node TEXT="作品集练习 · 25分钟"><node TEXT="挑选2—3项成果写案例页" /><node TEXT="标注制作范围、时间和工具角色" /></node><node TEXT="展示评议 · 10分钟"><node TEXT="模拟一分钟作品介绍" /><node TEXT="检查是否夸大真实委托、业绩或制作贡献" /></node></node><node TEXT="B04 发布与复盘：用数据决定下一版怎么改（1h）" COLOR="#935418"><node TEXT="用内容目标选择复盘指标，区分事实观察和原因假设，为下一版改动设计可比较的实验。" /><node TEXT="成果：一份基于教学数据的A/B复盘表" /><node TEXT="前置：—" /><node TEXT="指标选择 · 10分钟"><node TEXT="按观看、理解或行动目标选指标" /><node TEXT="说明曝光口径与观察周期" /></node><node TEXT="数据示范 · 15分钟"><node TEXT="读取一份匿名示例数据" /><node TEXT="区分相关性与可验证的解释" /></node><node TEXT="复盘练习 · 25分钟"><node TEXT="提出一项问题假设" /><node TEXT="设计只改变开头或信息顺序的版本" /></node><node TEXT="决策讲评 · 10分钟"><node TEXT="写明测试条件和保留标准" /><node TEXT="避免把小样本波动视为稳定结论" /></node></node><node TEXT="B05 系列化生产：把样片工作流保存为可复用工具（1h）" COLOR="#935418"><node TEXT="以已经跑通的画布样片流程为起点，学习设置产品名称、卖点、图片等输入字段，区分必填和选填，编组后保存为工具。用第二组内容验证复用，形成三期内容计划和版本记录。" /><node TEXT="成果：可复用工具字段表＋第二组输入验证记录＋三期内容计划" /><node TEXT="前置：—" /><node TEXT="提炼固定与变量 · 10分钟"><node TEXT="从已有样片节点链识别角色、风格和可变内容" /><node TEXT="明确工具的输入、输出与使用范围" /></node><node TEXT="表单与编组示范 · 15分钟"><node TEXT="在开始节点的字段表单设置中启用字段，区分必填和选填并保存" /><node TEXT="框选节点编组，命名后保存为工具" /></node><node TEXT="第二组内容验证 · 25分钟"><node TEXT="在工具分类中调用保存的工具，替换名称、卖点和图片" /><node TEXT="检查实际输入与候选，生成等待时使用预制验证记录对照" /></node><node TEXT="复用与版本评价 · 10分钟"><node TEXT="整理三期内容计划并记录每次改动" /><node TEXT="选择JSON或7Z备份，并人工核对不同内容的事实与素材" /></node></node><node TEXT="B06 作品诊断与路演：完成一次模拟验收（1h）" COLOR="#935418"><node TEXT="将作品、任务书和过程记录用于一次模拟客户验收，练习解释创作选择、回应问题与明确后续修改。" /><node TEXT="成果：一份作品诊断表与改进计划" /><node TEXT="前置：—" /><node TEXT="验收准备 · 10分钟"><node TEXT="对照任务书整理样片和过程记录" /><node TEXT="声明未完成事项" /></node><node TEXT="评审示范 · 15分钟"><node TEXT="按表达、视听和交付要求提出具体意见" /><node TEXT="区分质量问题与个人偏好" /></node><node TEXT="模拟路演 · 25分钟"><node TEXT="用三分钟介绍任务、方案与结果" /><node TEXT="同伴扮演客户提问并记录回应" /></node><node TEXT="修订总结 · 10分钟"><node TEXT="对意见排序并提出可执行计划" /><node TEXT="确定验收条件和后续练习" /></node></node></node></node></map>